import React, { useEffect, useMemo, useState } from 'react';
import { Reorder } from 'motion/react';
import { useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  BarChart3,
  BookOpen,
  Check,
  CheckCircle2,
  Eye,
  FileText,
  GripVertical,
  Layers,
  Loader2,
  Monitor,
  Moon,
  Palette,
  Play,
  Plus,
  Save,
  Search,
  Settings,
  Smartphone,
  Sun,
  Trash2,
  Video,
  X,
} from 'lucide-react';
import { FileUpload } from '../FileUpload';
import { supabase } from '../../lib/supabase';
import { useTheme } from '../../context/ThemeContext';
import { appToast } from '@/lib/feedback';

type LessonType = 'video' | 'text' | 'link' | 'audio' | 'pdf' | 'quiz';

interface Lesson {
  id: string;
  title: string;
  type: LessonType;
  content: string;
  videoUrl?: string;
  duration?: string;
  isFreePreview?: boolean;
  resources?: { name: string; url: string }[];
  quiz?: { question: string; options: string[]; correctAnswer: number }[];
}

interface Module {
  id: string;
  title: string;
  lessons: Lesson[];
  dripDays?: number;
}

interface CourseDesign {
  primaryColor: string;
  accentColor: string;
  buttonText: string;
  layout: 'sidebar' | 'grid';
  font: string;
  theme: string;
  borderRadius: string;
}

interface CourseSettings {
  commentsEnabled: boolean;
  dripEnabled: boolean;
  certificatesEnabled: boolean;
  gamificationEnabled: boolean;
}

interface CourseBuilderData {
  modules: Module[];
  design: CourseDesign;
  settings: CourseSettings;
}

interface CourseBuilderProps {
  initialData?: Partial<CourseBuilderData>;
  onSave: (data: CourseBuilderData) => void | Promise<void>;
  onCancel: () => void;
  listingId?: string;
}

const DEFAULT_MODULES: Module[] = [{
  id: '1',
  title: 'Introduction',
  lessons: [{
    id: '1-1',
    title: 'Episode 1 · Welcome to the course',
    type: 'video',
    content: '',
    duration: '',
  }],
}];

const DEFAULT_DESIGN: CourseDesign = {
  primaryColor: '#2563EB',
  accentColor: '#F59E0B',
  buttonText: 'Start learning',
  layout: 'sidebar',
  font: 'sans',
  theme: 'dark',
  borderRadius: 'xl',
};

const DEFAULT_SETTINGS: CourseSettings = {
  commentsEnabled: true,
  dripEnabled: false,
  certificatesEnabled: false,
  gamificationEnabled: false,
};

const createId = () => crypto.randomUUID?.() || Math.random().toString(36).slice(2);

const lessonIcon = (type: LessonType) => (
  type === 'video' ? Video : FileText
);

const findFirstLesson = (modules: Module[]) => {
  for (const module of modules) {
    if (module.lessons[0]) return { mId: module.id, lId: module.lessons[0].id };
  }
  return null;
};

const Switch = ({
  checked,
  onChange,
  label,
}: {
  checked: boolean;
  onChange: (checked: boolean) => void;
  label: string;
}) => (
  <label className="relative block h-7 w-12 shrink-0 cursor-pointer">
    <span className="sr-only">{label}</span>
    <input
      type="checkbox"
      checked={checked}
      onChange={(event) => onChange(event.target.checked)}
      className="peer sr-only"
    />
    <span className="absolute inset-0 rounded-full bg-gray-700 transition peer-checked:bg-blue-600 peer-focus-visible:ring-2 peer-focus-visible:ring-blue-500">
      <span className="absolute left-1 top-1 h-5 w-5 rounded-full bg-white transition-transform peer-checked:translate-x-5" />
    </span>
  </label>
);

const Toggle = ({
  checked,
  onChange,
  label,
  description,
}: {
  checked: boolean;
  onChange: (checked: boolean) => void;
  label: string;
  description: string;
}) => (
  <div className="flex items-center justify-between gap-6 py-4">
    <span>
      <span className="block text-sm font-semibold">{label}</span>
      <span className="mt-1 block text-sm text-gray-500">{description}</span>
    </span>
    <Switch checked={checked} onChange={onChange} label={label} />
  </div>
);

export const CourseBuilder = ({
  initialData,
  onSave,
  onCancel,
  listingId,
}: CourseBuilderProps) => {
  const navigate = useNavigate();
  const { isDark, toggleTheme } = useTheme();
  const initialModules = initialData?.modules?.length ? initialData.modules : DEFAULT_MODULES;
  const [activeTab, setActiveTab] = useState<'content' | 'design' | 'settings' | 'analytics'>('content');
  const [modules, setModules] = useState<Module[]>(initialModules);
  const [design, setDesign] = useState<CourseDesign>({ ...DEFAULT_DESIGN, ...initialData?.design });
  const [settings, setSettings] = useState<CourseSettings>({ ...DEFAULT_SETTINGS, ...initialData?.settings });
  const [selectedLesson, setSelectedLesson] = useState<{ mId: string; lId: string } | null>(
    findFirstLesson(initialModules),
  );
  const [searchQuery, setSearchQuery] = useState('');
  const [isMobile, setIsMobile] = useState(() => typeof window !== 'undefined' && window.innerWidth < 1024);
  const [showMobileCurriculum, setShowMobileCurriculum] = useState(false);
  const [saveState, setSaveState] = useState<'clean' | 'dirty' | 'saving' | 'saved' | 'error'>('clean');
  const [insightsLoading, setInsightsLoading] = useState(Boolean(listingId));
  const [insightsError, setInsightsError] = useState('');
  const [insightRows, setInsightRows] = useState<{
    orders: { amount: number | null; buyer_id: string | null }[];
    progress: { completed_lessons: string[] | null }[];
  }>({
    orders: [],
    progress: [],
  });

  const lessonCount = useMemo(
    () => modules.reduce((total, module) => total + module.lessons.length, 0),
    [modules],
  );

  const activeLesson = useMemo(() => {
    if (!selectedLesson) return null;
    return modules
      .find((module) => module.id === selectedLesson.mId)
      ?.lessons.find((lesson) => lesson.id === selectedLesson.lId) || null;
  }, [modules, selectedLesson]);

  const visibleModules = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();
    if (!query) return modules;
    return modules
      .map((module) => ({
        ...module,
        lessons: module.lessons.filter((lesson) =>
          lesson.title.toLowerCase().includes(query)
          || module.title.toLowerCase().includes(query)),
      }))
      .filter((module) => module.lessons.length > 0 || module.title.toLowerCase().includes(query));
  }, [modules, searchQuery]);

  const insights = useMemo(() => {
    const totalRevenue = insightRows.orders.reduce((sum, order) => sum + Number(order.amount || 0), 0);
    const uniqueStudents = new Set(insightRows.orders.map((order) => order.buyer_id).filter(Boolean)).size;
    const completion = insightRows.progress.length && lessonCount > 0
      ? Math.round(
          insightRows.progress.reduce(
            (total, row) => total + Math.min(100, ((row.completed_lessons?.length || 0) / lessonCount) * 100),
            0,
          ) / insightRows.progress.length,
        )
      : 0;
    const moduleCompletion = modules.map((module) => {
      if (!insightRows.progress.length || !module.lessons.length) {
        return { id: module.id, title: module.title, completion: 0 };
      }
      const lessonIds = new Set(module.lessons.map((lesson) => lesson.id));
      const completed = insightRows.progress.reduce(
        (total, row) => total + (row.completed_lessons || []).filter((id) => lessonIds.has(id)).length,
        0,
      );
      return {
        id: module.id,
        title: module.title,
        completion: Math.round((completed / (insightRows.progress.length * module.lessons.length)) * 100),
      };
    });

    return {
      revenue: totalRevenue,
      students: uniqueStudents,
      completion,
      moduleCompletion,
    };
  }, [insightRows, lessonCount, modules]);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    let cancelled = false;

    const fetchInsights = async () => {
      if (!listingId) {
        setInsightsLoading(false);
        return;
      }

      setInsightsLoading(true);
      setInsightsError('');
      const [{ data: orders, error: ordersError }, { data: progressRows, error: progressError }] = await Promise.all([
        supabase.from('orders').select('amount, buyer_id').eq('listing_id', listingId),
        supabase.from('course_progress').select('completed_lessons').eq('listing_id', listingId),
      ]);

      if (cancelled) return;
      if (ordersError || progressError) {
        console.error('Course insights could not be loaded:', ordersError || progressError);
        setInsightsError('Insights are temporarily unavailable.');
        setInsightsLoading(false);
        return;
      }

      setInsightRows({
        orders: (orders || []) as { amount: number | null; buyer_id: string | null }[],
        progress: (progressRows || []) as { completed_lessons: string[] | null }[],
      });
      setInsightsLoading(false);
    };

    fetchInsights();
    return () => {
      cancelled = true;
    };
  }, [listingId]);

  const markDirty = () => setSaveState('dirty');

  const replaceModules = (nextModules: Module[]) => {
    setModules(nextModules);
    markDirty();
  };

  const addModule = () => {
    const moduleId = createId();
    const lessonId = createId();
    replaceModules([
      ...modules,
      {
        id: moduleId,
        title: `Module ${modules.length + 1}`,
        lessons: [{ id: lessonId, title: 'Untitled lesson', type: 'video', content: '', duration: '' }],
        dripDays: 0,
      },
    ]);
    setSelectedLesson({ mId: moduleId, lId: lessonId });
  };

  const addLesson = (moduleId: string) => {
    const lessonId = createId();
    replaceModules(modules.map((module) => (
      module.id === moduleId
        ? {
            ...module,
            lessons: [
              ...module.lessons,
              {
                id: lessonId,
                title: `Episode ${module.lessons.length + 1}`,
                type: 'video',
                content: '',
                duration: '',
              },
            ],
          }
        : module
    )));
    setSelectedLesson({ mId: moduleId, lId: lessonId });
  };

  const updateModule = (moduleId: string, updates: Partial<Module>) => {
    replaceModules(modules.map((module) => (
      module.id === moduleId ? { ...module, ...updates } : module
    )));
  };

  const removeModule = (moduleId: string) => {
    const nextModules = modules.filter((module) => module.id !== moduleId);
    replaceModules(nextModules);
    if (selectedLesson?.mId === moduleId) setSelectedLesson(findFirstLesson(nextModules));
  };

  const updateLesson = (moduleId: string, lessonId: string, updates: Partial<Lesson>) => {
    replaceModules(modules.map((module) => (
      module.id === moduleId
        ? {
            ...module,
            lessons: module.lessons.map((lesson) => (
              lesson.id === lessonId ? { ...lesson, ...updates } : lesson
            )),
          }
        : module
    )));
  };

  const removeLesson = (moduleId: string, lessonId: string) => {
    const nextModules = modules.map((module) => (
      module.id === moduleId
        ? { ...module, lessons: module.lessons.filter((lesson) => lesson.id !== lessonId) }
        : module
    ));
    replaceModules(nextModules);
    setSelectedLesson(findFirstLesson(nextModules));
  };

  const updateDesign = (updates: Partial<CourseDesign>) => {
    setDesign((current) => ({ ...current, ...updates }));
    markDirty();
  };

  const updateSettings = (updates: Partial<CourseSettings>) => {
    setSettings((current) => ({ ...current, ...updates }));
    markDirty();
  };

  const handleSave = async () => {
    setSaveState('saving');
    try {
      await onSave({ modules, design, settings });
      setSaveState('saved');
    } catch (error) {
      console.error('Course could not be saved:', error);
      setSaveState('error');
      appToast('The course could not be saved. Please try again.');
    }
  };

  const openPreview = () => {
    if (listingId) {
      navigate(`/access/${listingId}`);
      return;
    }
    appToast('Save the product draft before opening the preview.');
  };

  const saveLabel = saveState === 'saving'
    ? 'Saving…'
    : saveState === 'saved'
      ? 'Saved'
      : 'Save course';

  return (
    <div className={`fixed inset-0 z-[100] flex flex-col font-sans ${isDark ? 'bg-[#070707] text-white' : 'bg-[#f7f7f8] text-[#18181b]'}`}>
      <header className={`z-50 flex h-16 shrink-0 items-center justify-between overflow-hidden border-b px-3 md:px-6 ${isDark ? 'border-white/10 bg-[#090909]' : 'border-black/10 bg-white'}`}>
        <div className="flex min-w-0 items-center gap-2 md:gap-4">
          <button
            type="button"
            onClick={onCancel}
            aria-label="Close course builder"
            className={`rounded-xl p-2 transition ${isDark ? 'text-gray-400 hover:bg-white/10 hover:text-white' : 'text-gray-500 hover:bg-black/5 hover:text-black'}`}
          >
            <X className="h-5 w-5" />
          </button>
          <div className="hidden min-w-0 sm:block">
            <h1 className="truncate text-sm font-semibold md:text-base">Course Builder</h1>
            <p className="text-xs text-gray-500">
              {lessonCount} {lessonCount === 1 ? 'lesson' : 'lessons'}
              {saveState === 'dirty' ? ' · Unsaved changes' : ''}
              {saveState === 'error' ? ' · Save failed' : ''}
            </p>
          </div>
          <nav className={`ml-1 flex rounded-xl p-1 md:ml-4 ${isDark ? 'bg-white/[0.06]' : 'bg-black/[0.04]'}`} aria-label="Course builder sections">
            {[
              { id: 'content', icon: Layers, label: 'Build' },
              { id: 'design', icon: Palette, label: 'Design' },
              { id: 'settings', icon: Settings, label: 'Settings' },
              { id: 'analytics', icon: BarChart3, label: 'Insights' },
            ].map((tab) => (
              <button
                type="button"
                key={tab.id}
                onClick={() => setActiveTab(tab.id as typeof activeTab)}
                className={`flex items-center gap-2 rounded-lg px-2.5 py-2 text-xs font-semibold transition md:px-4 ${
                  activeTab === tab.id
                    ? isDark ? 'bg-white/10 text-white' : 'bg-white text-black shadow-sm'
                    : 'text-gray-500 hover:text-current'
                }`}
              >
                <tab.icon className="h-4 w-4" />
                <span className="hidden md:inline">{tab.label}</span>
              </button>
            ))}
          </nav>
        </div>

        <div className="flex items-center gap-1.5 md:gap-2">
          {!isMobile ? (
            <>
              <button
                type="button"
                onClick={toggleTheme}
                aria-label={isDark ? 'Use light theme' : 'Use dark theme'}
                className={`rounded-xl p-2.5 transition ${isDark ? 'text-gray-400 hover:bg-white/10 hover:text-white' : 'text-gray-500 hover:bg-black/5 hover:text-black'}`}
              >
                {isDark ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}
              </button>
              <button
                type="button"
                onClick={openPreview}
                className={`flex items-center gap-2 rounded-xl px-3 py-2.5 text-xs font-semibold transition ${isDark ? 'text-gray-300 hover:bg-white/10' : 'text-gray-600 hover:bg-black/5'}`}
              >
                <Eye className="h-4 w-4" />
                Preview
              </button>
            </>
          ) : null}
          <button
            type="button"
            onClick={handleSave}
            disabled={saveState === 'saving'}
            className={`flex min-w-11 items-center justify-center gap-2 rounded-xl px-3 py-2.5 text-xs font-semibold transition disabled:cursor-wait disabled:opacity-70 md:min-w-32 md:px-5 ${
              isDark ? 'bg-white text-black hover:bg-gray-200' : 'bg-black text-white hover:bg-gray-800'
            }`}
          >
            {saveState === 'saving'
              ? <Loader2 className="h-4 w-4 animate-spin" />
              : saveState === 'saved'
                ? <Check className="h-4 w-4" />
                : <Save className="h-4 w-4" />}
            <span className="hidden md:inline">{saveLabel}</span>
          </button>
        </div>
      </header>

      <div className="relative flex min-h-0 flex-1 overflow-hidden">
        {activeTab === 'content' ? (
          <>
            <aside className={`
              ${isMobile
                ? `fixed inset-x-0 bottom-0 top-16 z-40 ${showMobileCurriculum ? 'translate-x-0' : '-translate-x-full'}`
                : 'relative w-80 translate-x-0 border-r'}
              flex shrink-0 flex-col transition-transform duration-200
              ${isDark ? 'border-white/10 bg-[#0b0b0b]' : 'border-black/10 bg-white'}
            `}>
              <div className="space-y-4 border-b border-current/10 p-4">
                <div className="flex items-center justify-between">
                  <div>
                    <h2 className="text-sm font-semibold">Curriculum</h2>
                    <p className="text-xs text-gray-500">{modules.length} {modules.length === 1 ? 'module' : 'modules'}</p>
                  </div>
                  <div className="flex items-center gap-1">
                    {isMobile ? (
                      <button type="button" onClick={() => setShowMobileCurriculum(false)} className="rounded-lg p-2 text-gray-500 hover:bg-current/10" aria-label="Close curriculum">
                        <X className="h-4 w-4" />
                      </button>
                    ) : null}
                    <button
                      type="button"
                      onClick={addModule}
                      className={`flex items-center gap-1.5 rounded-lg px-3 py-2 text-xs font-semibold ${isDark ? 'bg-white text-black' : 'bg-black text-white'}`}
                    >
                      <Plus className="h-4 w-4" />
                      Module
                    </button>
                  </div>
                </div>
                <label className={`flex items-center gap-2 rounded-lg border px-3 py-2 ${isDark ? 'border-white/10 bg-white/[0.04]' : 'border-black/10 bg-black/[0.02]'}`}>
                  <Search className="h-4 w-4 text-gray-500" />
                  <input
                    value={searchQuery}
                    onChange={(event) => setSearchQuery(event.target.value)}
                    placeholder="Search lessons"
                    className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-gray-500"
                  />
                </label>
              </div>

              <div className="min-h-0 flex-1 overflow-y-auto p-3">
                {visibleModules.length ? (
                  <Reorder.Group
                    axis="y"
                    values={modules}
                    onReorder={searchQuery ? () => undefined : replaceModules}
                    className="space-y-3"
                  >
                    {visibleModules.map((module) => (
                      <Reorder.Item key={module.id} value={module} dragListener={!searchQuery}>
                        <section className={`overflow-hidden rounded-2xl border ${isDark ? 'border-white/10 bg-white/[0.035]' : 'border-black/10 bg-black/[0.02]'}`}>
                          <div className="group flex items-center gap-2 border-b border-current/10 px-3 py-3">
                            <GripVertical className="h-4 w-4 shrink-0 cursor-grab text-gray-600" />
                            <input
                              value={module.title}
                              onChange={(event) => updateModule(module.id, { title: event.target.value })}
                              aria-label="Module title"
                              className="min-w-0 flex-1 bg-transparent text-sm font-semibold outline-none"
                            />
                            <button
                              type="button"
                              onClick={() => removeModule(module.id)}
                              aria-label={`Delete ${module.title}`}
                              className="rounded-lg p-1.5 text-gray-600 opacity-100 transition hover:bg-red-500/10 hover:text-red-500 md:opacity-0 md:group-hover:opacity-100"
                            >
                              <Trash2 className="h-4 w-4" />
                            </button>
                          </div>

                          <Reorder.Group
                            axis="y"
                            values={module.lessons}
                            onReorder={(lessons) => updateModule(module.id, { lessons })}
                            className="space-y-1 p-2"
                          >
                            {module.lessons.map((lesson) => {
                              const LessonIcon = lessonIcon(lesson.type);
                              const isSelected = selectedLesson?.mId === module.id && selectedLesson?.lId === lesson.id;
                              return (
                                <Reorder.Item key={lesson.id} value={lesson}>
                                  <button
                                    type="button"
                                    onClick={() => {
                                      setSelectedLesson({ mId: module.id, lId: lesson.id });
                                      setShowMobileCurriculum(false);
                                    }}
                                    className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left transition ${
                                      isSelected
                                        ? isDark ? 'bg-white/10 text-white' : 'bg-white shadow-sm'
                                        : 'text-gray-500 hover:bg-current/5 hover:text-current'
                                    }`}
                                  >
                                    <span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-lg ${lesson.type === 'video' ? 'bg-blue-500/15 text-blue-500' : 'bg-gray-500/10 text-gray-500'}`}>
                                      <LessonIcon className="h-4 w-4" />
                                    </span>
                                    <span className="min-w-0 flex-1">
                                      <span className="block truncate text-xs font-semibold">{lesson.title || 'Untitled lesson'}</span>
                                      <span className="mt-0.5 block text-[11px] capitalize text-gray-600">{lesson.type}</span>
                                    </span>
                                    {lesson.videoUrl || lesson.content ? <CheckCircle2 className="h-4 w-4 shrink-0 text-emerald-500" /> : null}
                                  </button>
                                </Reorder.Item>
                              );
                            })}
                          </Reorder.Group>

                          <button
                            type="button"
                            onClick={() => addLesson(module.id)}
                            className="flex w-full items-center justify-center gap-1.5 border-t border-current/10 py-2.5 text-xs font-semibold text-gray-500 transition hover:bg-current/5 hover:text-current"
                          >
                            <Plus className="h-3.5 w-3.5" />
                            Add lesson
                          </button>
                        </section>
                      </Reorder.Item>
                    ))}
                  </Reorder.Group>
                ) : (
                  <div className="px-4 py-12 text-center text-sm text-gray-500">
                    {searchQuery ? 'No matching lessons.' : 'Add your first module to start building.'}
                  </div>
                )}
              </div>
            </aside>

            <main className="min-w-0 flex-1 overflow-y-auto">
              {activeLesson && selectedLesson ? (
                <div className="mx-auto max-w-4xl space-y-8 px-4 py-6 md:px-10 md:py-10">
                  <div className="flex items-start gap-3">
                    {isMobile ? (
                      <button
                        type="button"
                        onClick={() => setShowMobileCurriculum(true)}
                        className={`mt-1 rounded-xl p-2 ${isDark ? 'bg-white/10' : 'bg-black/5'}`}
                        aria-label="Open curriculum"
                      >
                        <ArrowLeft className="h-4 w-4" />
                      </button>
                    ) : null}
                    <div className="min-w-0 flex-1">
                      <select
                        value={activeLesson.type}
                        onChange={(event) => updateLesson(selectedLesson.mId, selectedLesson.lId, { type: event.target.value as LessonType })}
                        className="mb-2 bg-transparent text-xs font-semibold uppercase tracking-wider text-gray-500 outline-none"
                        aria-label="Lesson type"
                      >
                        <option value="video">Video lesson</option>
                        <option value="text">Text lesson</option>
                        <option value="link">Link lesson</option>
                        <option value="audio">Audio lesson</option>
                        <option value="pdf">PDF lesson</option>
                        <option value="quiz">Quiz lesson</option>
                      </select>
                      <input
                        value={activeLesson.title}
                        onChange={(event) => updateLesson(selectedLesson.mId, selectedLesson.lId, { title: event.target.value })}
                        className="w-full bg-transparent text-xl font-semibold tracking-tight outline-none md:text-3xl"
                        placeholder="Lesson title"
                        aria-label="Lesson title"
                      />
                    </div>
                    <button
                      type="button"
                      onClick={() => removeLesson(selectedLesson.mId, selectedLesson.lId)}
                      className="rounded-xl p-2.5 text-gray-500 transition hover:bg-red-500/10 hover:text-red-500"
                      aria-label="Delete lesson"
                    >
                      <Trash2 className="h-5 w-5" />
                    </button>
                  </div>

                  {activeLesson.type === 'video' ? (
                    <section>
                      {activeLesson.videoUrl ? (
                        <div className="group relative aspect-video overflow-hidden rounded-2xl bg-black">
                          <video src={activeLesson.videoUrl} controls className="h-full w-full object-contain" />
                          <button
                            type="button"
                            onClick={() => updateLesson(selectedLesson.mId, selectedLesson.lId, { videoUrl: '' })}
                            className="absolute right-3 top-3 rounded-lg bg-black/70 p-2 text-white opacity-100 backdrop-blur transition hover:bg-black md:opacity-0 md:group-hover:opacity-100"
                            aria-label="Remove video"
                          >
                            <X className="h-4 w-4" />
                          </button>
                        </div>
                      ) : (
                        <div className={`flex aspect-video flex-col items-center justify-center rounded-2xl border border-dashed px-6 text-center ${isDark ? 'border-white/15 bg-white/[0.025]' : 'border-black/15 bg-white'}`}>
                          <span className="mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-blue-500/10 text-blue-500">
                            <Play className="h-6 w-6" />
                          </span>
                          <h3 className="text-sm font-semibold">Upload your lesson video</h3>
                          <p className="mb-5 mt-1 text-xs text-gray-500">STRATO-first storage with automatic Supabase backup · max 2 GB</p>
                          <div className="w-full max-w-56">
                            <FileUpload
                              bucket="course-videos"
                              logicalPathPrefix={`courses/${listingId || 'drafts'}/${selectedLesson.lId}`}
                              onUpload={(url) => updateLesson(selectedLesson.mId, selectedLesson.lId, { videoUrl: url })}
                              accept="video/mp4,video/webm,video/ogg,video/quicktime"
                              maxSizeMB={2048}
                              darkMode={isDark}
                              customTrigger={(
                                <span className={`flex w-full items-center justify-center gap-2 rounded-xl px-4 py-3 text-sm font-semibold ${isDark ? 'bg-white text-black' : 'bg-black text-white'}`}>
                                  <Video className="h-4 w-4" />
                                  Choose video
                                </span>
                              )}
                            />
                          </div>
                        </div>
                      )}
                    </section>
                  ) : null}

                  {activeLesson.type === 'link' ? (
                    <label className="block space-y-2">
                      <span className="text-sm font-semibold">Destination URL</span>
                      <input
                        type="url"
                        value={activeLesson.content}
                        onChange={(event) => updateLesson(selectedLesson.mId, selectedLesson.lId, { content: event.target.value })}
                        placeholder="https://"
                        className={`w-full rounded-xl border px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-blue-500/30 ${isDark ? 'border-white/10 bg-white/[0.04]' : 'border-black/10 bg-white'}`}
                      />
                    </label>
                  ) : (
                    <label className="block space-y-2">
                      <span className="text-sm font-semibold">
                        {activeLesson.type === 'video' ? 'Lesson description' : 'Lesson content'}
                      </span>
                      <textarea
                        value={activeLesson.content}
                        onChange={(event) => updateLesson(selectedLesson.mId, selectedLesson.lId, { content: event.target.value })}
                        placeholder="Add the content students need for this lesson…"
                        className={`min-h-48 w-full resize-y rounded-2xl border p-5 text-sm leading-6 outline-none focus:ring-2 focus:ring-blue-500/30 md:min-h-64 ${isDark ? 'border-white/10 bg-white/[0.04] text-gray-200' : 'border-black/10 bg-white'}`}
                      />
                    </label>
                  )}

                  <div className={`flex flex-col gap-4 rounded-2xl border p-4 sm:flex-row sm:items-center sm:justify-between ${isDark ? 'border-white/10 bg-white/[0.025]' : 'border-black/10 bg-white'}`}>
                    <div>
                      <p className="text-sm font-semibold">Free preview</p>
                      <p className="text-xs text-gray-500">Let visitors view this lesson before buying.</p>
                    </div>
                    <Switch
                      checked={Boolean(activeLesson.isFreePreview)}
                      onChange={(checked) => updateLesson(selectedLesson.mId, selectedLesson.lId, { isFreePreview: checked })}
                      label="Free preview"
                    />
                  </div>
                </div>
              ) : (
                <div className="flex h-full min-h-[480px] flex-col items-center justify-center px-6 text-center">
                  {isMobile ? (
                    <button
                      type="button"
                      onClick={() => setShowMobileCurriculum(true)}
                      className={`mb-6 flex items-center gap-2 rounded-xl px-4 py-3 text-sm font-semibold ${isDark ? 'bg-white text-black' : 'bg-black text-white'}`}
                    >
                      <Layers className="h-4 w-4" />
                      Open curriculum
                    </button>
                  ) : (
                    <span className="mb-5 flex h-16 w-16 items-center justify-center rounded-2xl bg-blue-500/10 text-blue-500">
                      <BookOpen className="h-7 w-7" />
                    </span>
                  )}
                  <h2 className="text-xl font-semibold">Select a lesson</h2>
                  <p className="mt-2 max-w-sm text-sm text-gray-500">Choose a lesson from the curriculum or add a new module.</p>
                </div>
              )}
            </main>
          </>
        ) : null}

        {activeTab === 'design' ? (
          <main className="w-full overflow-y-auto">
            <div className="mx-auto grid max-w-5xl gap-10 px-5 py-8 lg:grid-cols-[minmax(0,1fr)_minmax(320px,0.8fr)] lg:px-10 lg:py-12">
              <div className="space-y-8">
                <div>
                  <h2 className="text-2xl font-semibold">Course appearance</h2>
                  <p className="mt-1 text-sm text-gray-500">Keep the learning environment focused and on-brand.</p>
                </div>
                <section className="grid gap-5 sm:grid-cols-2">
                  {[
                    { key: 'primaryColor' as const, label: 'Primary color' },
                    { key: 'accentColor' as const, label: 'Accent color' },
                  ].map((color) => (
                    <label key={color.key} className="space-y-2">
                      <span className="text-sm font-semibold">{color.label}</span>
                      <span className={`flex items-center gap-3 rounded-xl border p-3 ${isDark ? 'border-white/10 bg-white/[0.04]' : 'border-black/10 bg-white'}`}>
                        <input
                          type="color"
                          value={design[color.key]}
                          onChange={(event) => updateDesign({ [color.key]: event.target.value })}
                          className="h-9 w-9 cursor-pointer rounded-lg border-0 bg-transparent p-0"
                        />
                        <input
                          value={design[color.key]}
                          onChange={(event) => updateDesign({ [color.key]: event.target.value })}
                          className="min-w-0 flex-1 bg-transparent font-mono text-sm uppercase outline-none"
                        />
                      </span>
                    </label>
                  ))}
                </section>
                <section className="space-y-3">
                  <h3 className="text-sm font-semibold">Layout</h3>
                  <div className="grid grid-cols-2 gap-3">
                    {[
                      { id: 'sidebar' as const, label: 'Sidebar', icon: Monitor },
                      { id: 'grid' as const, label: 'Grid', icon: Smartphone },
                    ].map((layout) => (
                      <button
                        type="button"
                        key={layout.id}
                        onClick={() => updateDesign({ layout: layout.id })}
                        className={`flex items-center gap-3 rounded-xl border p-4 text-left text-sm font-semibold transition ${
                          design.layout === layout.id
                            ? 'border-blue-500 bg-blue-500/10 text-blue-500'
                            : isDark ? 'border-white/10 bg-white/[0.025]' : 'border-black/10 bg-white'
                        }`}
                      >
                        <layout.icon className="h-5 w-5" />
                        {layout.label}
                      </button>
                    ))}
                  </div>
                </section>
              </div>

              <section>
                <p className="mb-3 text-xs font-semibold uppercase tracking-wider text-gray-500">Preview</p>
                <div className={`overflow-hidden rounded-3xl border shadow-2xl ${isDark ? 'border-white/10 bg-[#111]' : 'border-black/10 bg-white'}`}>
                  <div className="flex h-10 items-center gap-1.5 border-b border-current/10 px-4">
                    <span className="h-2 w-2 rounded-full bg-red-400" />
                    <span className="h-2 w-2 rounded-full bg-amber-400" />
                    <span className="h-2 w-2 rounded-full bg-emerald-400" />
                  </div>
                  <div className="flex min-h-[420px]">
                    {design.layout === 'sidebar' ? <div className="w-20 border-r border-current/10 bg-current/[0.025]" /> : null}
                    <div className="flex-1 space-y-5 p-6">
                      <div className="h-3 w-1/2 rounded bg-current/10" />
                      <div className="aspect-video rounded-xl bg-black" />
                      <div className="space-y-2">
                        <div className="h-2.5 rounded bg-current/[0.07]" />
                        <div className="h-2.5 w-3/4 rounded bg-current/[0.07]" />
                      </div>
                      <div className="h-10 rounded-xl" style={{ backgroundColor: design.primaryColor }} />
                    </div>
                  </div>
                </div>
              </section>
            </div>
          </main>
        ) : null}

        {activeTab === 'settings' ? (
          <main className="w-full overflow-y-auto">
            <div className="mx-auto max-w-2xl px-5 py-8 md:px-10 md:py-12">
              <h2 className="text-2xl font-semibold">Course settings</h2>
              <p className="mt-1 text-sm text-gray-500">Only enabled features are saved with this course.</p>
              <section className={`mt-8 divide-y rounded-2xl border px-5 ${isDark ? 'divide-white/10 border-white/10 bg-white/[0.025]' : 'divide-black/10 border-black/10 bg-white'}`}>
                <Toggle
                  checked={settings.commentsEnabled}
                  onChange={(checked) => updateSettings({ commentsEnabled: checked })}
                  label="Lesson comments"
                  description="Allow students to discuss lesson content."
                />
                <Toggle
                  checked={settings.dripEnabled}
                  onChange={(checked) => updateSettings({ dripEnabled: checked })}
                  label="Drip schedule"
                  description="Use each module’s release delay."
                />
                <Toggle
                  checked={settings.certificatesEnabled}
                  onChange={(checked) => updateSettings({ certificatesEnabled: checked })}
                  label="Completion certificates"
                  description="Issue a certificate after all lessons are completed."
                />
                <Toggle
                  checked={settings.gamificationEnabled}
                  onChange={(checked) => updateSettings({ gamificationEnabled: checked })}
                  label="Gamification"
                  description="Enable course points and achievements."
                />
              </section>
            </div>
          </main>
        ) : null}

        {activeTab === 'analytics' ? (
          <main className="w-full overflow-y-auto">
            <div className="mx-auto max-w-5xl px-5 py-8 md:px-10 md:py-12">
              <h2 className="text-2xl font-semibold">Course insights</h2>
              <p className="mt-1 text-sm text-gray-500">Based on real orders and lesson progress for this listing.</p>

              {!listingId ? (
                <div className={`mt-8 rounded-2xl border p-8 text-center ${isDark ? 'border-white/10 bg-white/[0.025]' : 'border-black/10 bg-white'}`}>
                  <BarChart3 className="mx-auto h-7 w-7 text-gray-500" />
                  <p className="mt-3 text-sm font-semibold">Save the product draft to start collecting insights.</p>
                </div>
              ) : insightsLoading ? (
                <div className="flex items-center justify-center py-24 text-gray-500">
                  <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                  Loading insights…
                </div>
              ) : insightsError ? (
                <div className="mt-8 rounded-2xl border border-red-500/20 bg-red-500/5 p-6 text-sm text-red-500">{insightsError}</div>
              ) : (
                <>
                  <div className="mt-8 grid gap-4 sm:grid-cols-3">
                    {[
                      { label: 'Revenue', value: `€${insights.revenue.toLocaleString()}` },
                      { label: 'Students', value: insights.students.toLocaleString() },
                      { label: 'Average completion', value: `${insights.completion}%` },
                    ].map((stat) => (
                      <div key={stat.label} className={`rounded-2xl border p-5 ${isDark ? 'border-white/10 bg-white/[0.025]' : 'border-black/10 bg-white'}`}>
                        <p className="text-xs font-semibold uppercase tracking-wider text-gray-500">{stat.label}</p>
                        <p className="mt-2 text-2xl font-semibold">{stat.value}</p>
                      </div>
                    ))}
                  </div>
                  <section className={`mt-5 rounded-2xl border p-5 ${isDark ? 'border-white/10 bg-white/[0.025]' : 'border-black/10 bg-white'}`}>
                    <h3 className="text-sm font-semibold">Completion by module</h3>
                    <div className="mt-5 space-y-5">
                      {insights.moduleCompletion.map((module) => (
                        <div key={module.id}>
                          <div className="mb-2 flex justify-between gap-4 text-sm">
                            <span className="truncate font-medium">{module.title}</span>
                            <span className="text-gray-500">{module.completion}%</span>
                          </div>
                          <div className="h-2 overflow-hidden rounded-full bg-gray-500/15">
                            <div className="h-full rounded-full bg-blue-500" style={{ width: `${module.completion}%` }} />
                          </div>
                        </div>
                      ))}
                    </div>
                  </section>
                </>
              )}
            </div>
          </main>
        ) : null}
      </div>
    </div>
  );
};
